        candidates.remove(idx)
        return np.random.choice(candidates, 3, replace=False)

    def mutate(self, idx, parents):
        if self.mutation_strategy == 'current-to-best':
            x1, x2 = self.population[parents[:2]]
            return self.population[idx] + self.F * (self.best_solution - self.population[idx]) + self.F * (x1 - x2)
        else:
            x1, x2, x3 = self.population[parents]
            return x1 + self.F * (x2 - x3)

    def crossover(self, target, mutant):
