        if not np.any(cross_points):
            cross_points[np.random.randint(0, self.dim)] = True
        return np.where(cross_points, mutant, target)

    def accept_solution(self, current_fitness, trial_fitness):
        if trial_fitness < current_fitness:
            return True
        else:
            acceptance_prob = np.exp((current_fitness - trial_fitness) / self.temperature)
            return np.random.rand() < acceptance_prob

    def adapt_parameters(self, iter_num, fitness):
        fitness_diversity = np.std(fitness) / np.mean(fitness)
